+    private CancellationTokenSource? _cts;
+
+    [Parameter]
+    public int CuisineId { get; set; }
+
+    [SupplyParameterFromQuery(Name = "sort")]
+    public string? Sort { get; set; }
+
+    private IReadOnlyList<Recipe> SortedRecipes =>
+        _recipes is null
+            ? Array.Empty<Recipe>()
+            : (Sort?.ToLowerInvariant()) switch
+            {
+                "popular" => _recipes.OrderBy(r => r.PrepTimeMinutes).ToList(),
+                _ => _recipes.OrderByDescending(r => r.Id).ToList(),
+            };
+
+    protected override async Task OnParametersSetAsync()
+    {
+        if (CuisineId == _loadedCuisineId)
+        {
+            // Only sort changed — no reload needed.
+            return;
+        }
+
+        await LoadRecipesAsync();
+    }
+
+    private async Task LoadRecipesAsync()
+    {
+        // Cancel any in-flight request for a previous cuisine.
+        CancelPendingLoad();
+
+        _errorMessage = null;
+        _isRefreshing = _recipes is not null;
+
+        if (!_isRefreshing)
+        {
+            // First load — clear everything so the loading placeholder shows.
+            _recipes = null;
+        }
+
+        var cts = new CancellationTokenSource();
+        _cts = cts;
+
+        try
+        {
+            var result = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);
+
+            // Guard against a stale callback after cancellation.
+            if (cts.Token.IsCancellationRequested)
+            {
+                return;
+            }
+
+            _recipes = result;
+            _loadedCuisineId = CuisineId;
+            _isRefreshing = false;
+        }
+        catch (OperationCanceledException) when (cts.Token.IsCancellationRequested)
+        {
+            // Expected when the user switched cuisines or navigated away.
+        }
+        catch (TimeoutException ex)
+        {
+            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
+            _errorMessage = "The request timed out. Please try again.";
+            _isRefreshing = false;
+        }
+        catch (Exception ex)
+        {
+            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
+            _errorMessage = "Something went wrong while loading recipes. Please try again.";
+            _isRefreshing = false;
+        }
+    }
+
+    private async Task RetryAsync()
+    {
+        await LoadRecipesAsync();
+    }
+
+    private void CancelPendingLoad()
+    {
+        if (_cts is not null)
+        {
+            _cts.Cancel();
+            _cts.Dispose();
+            _cts = null;
+        }
+    }
+
+    public void Dispose()
+    {
+        CancelPendingLoad();
+    }
+}
